'use client';

import { useId, useRef, type KeyboardEvent, type ReactNode } from 'react';
import { AutoHeight } from './auto-height';
import './detail-accordion.css';

export interface DetailAccordionItem {
  id: string;
  title: string;
  summary?: ReactNode;
  icon?: ReactNode;
  children: ReactNode;
  /** Critical errors and permission messages belong here, outside the collapsing panel. */
  notice?: ReactNode;
  disabled?: boolean;
}

export interface DetailAccordionProps {
  items: readonly DetailAccordionItem[];
  openItems: readonly string[];
  onOpenChange: (openItems: string[]) => void;
  label: string;
  className?: string;
  headingLevel?: 2 | 3 | 4;
}

/** Caller-controlled, independently expandable sections. Children remain mounted. */
export function DetailAccordion({ items, openItems, onOpenChange, label, className = '', headingLevel = 3 }: DetailAccordionProps) {
  const uid = useId();
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const Heading = `h${headingLevel}` as 'h2' | 'h3' | 'h4';
  function navigate(event: KeyboardEvent<HTMLButtonElement>, id: string) {
    const enabled = items.filter(item => !item.disabled);
    const index = enabled.findIndex(item => item.id === id);
    let next: number;
    switch (event.key) {
      case 'ArrowDown': next = (index + 1) % enabled.length; break;
      case 'ArrowUp': next = (index + enabled.length - 1) % enabled.length; break;
      case 'Home': next = 0; break;
      case 'End': next = enabled.length - 1; break;
      default: return;
    }
    event.preventDefault();
    buttons.current.get(enabled[next].id)?.focus();
  }
  return <section className={`mf-detail-accordion ${className}`} aria-label={label}>
    {items.map(item => {
      const open = openItems.includes(item.id);
      const triggerId = `${uid}-${item.id}-trigger`;
      const panelId = `${uid}-${item.id}-panel`;
      const summaryId = `${uid}-${item.id}-summary`;
      const noticeId = `${uid}-${item.id}-notice`;
      const titleId = `${uid}-${item.id}-title`;
      return <div key={item.id} className="mf-detail-accordion__item" data-open={open}>
        <Heading className="mf-detail-accordion__heading">
          <button type="button" id={triggerId} className="mf-detail-accordion__trigger"
            ref={element => { if (element) buttons.current.set(item.id, element); else buttons.current.delete(item.id); }}
            aria-expanded={open} aria-controls={panelId} aria-labelledby={titleId} disabled={item.disabled}
            aria-describedby={[item.summary ? summaryId : '', item.notice ? noticeId : ''].filter(Boolean).join(' ') || undefined}
            onKeyDown={event => navigate(event, item.id)}
            onClick={() => onOpenChange(open ? openItems.filter(id => id !== item.id) : [...openItems, item.id])}>
            {item.icon && <span className="mf-detail-accordion__icon" aria-hidden="true">{item.icon}</span>}
            <span className="mf-detail-accordion__labels"><span id={titleId}>{item.title}</span>
              {item.summary && <span id={summaryId} className="mf-detail-accordion__summary">{item.summary}</span>}
            </span>
            <svg className="mf-detail-accordion__chevron" aria-hidden="true" viewBox="0 0 20 20" fill="none"><path d="m6 8 4 4 4-4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
        </Heading>
        <AutoHeight className="mf-detail-accordion__reveal" collapsed={!open} id={panelId} role="region" aria-labelledby={triggerId} aria-hidden={!open} inert={!open}>
          <div className="mf-detail-accordion__panel">{item.children}</div>
        </AutoHeight>
        {item.notice && <div id={noticeId} className="mf-detail-accordion__notice">{item.notice}</div>}
      </div>;
    })}
  </section>;
}

.mf-detail-accordion{--mf-detail-ink:#0a0a0a;--mf-detail-muted:#737373;color:var(--mf-detail-ink);font-family:inherit;width:100%;min-width:0;border:1px solid #e5e5e5;background:#ffffff;border-radius:14px}
.mf-detail-accordion,.mf-detail-accordion *{box-sizing:border-box}
.mf-detail-accordion__item+.mf-detail-accordion__item{border-top:1px solid #e5e5e5}
.mf-detail-accordion__heading{margin:0;font:inherit}
.mf-detail-accordion__trigger{appearance:none;width:100%;border:0;border-radius:11px;background:transparent;display:flex;align-items:center;gap:12px;padding:16px;text-align:left;font:inherit;font-size:14px;font-weight:550;color:inherit;cursor:pointer;transition:background-color 130ms ease}
.mf-detail-accordion__trigger:hover:not(:disabled){background:#f5f5f5}
.mf-detail-accordion__trigger:hover:not(:disabled) .mf-detail-accordion__summary{color:#525252}
.mf-detail-accordion__trigger:focus-visible{outline:2px solid #737373;outline-offset:2px;position:relative;z-index:2}
.mf-detail-accordion__trigger:disabled{opacity:1;color:var(--mf-detail-muted);cursor:not-allowed}
.mf-detail-accordion__labels{display:flex;flex:1;min-width:0;flex-direction:column;gap:4px;overflow-wrap:anywhere}
.mf-detail-accordion__summary{font-size:12px;font-weight:400;line-height:1.45;color:var(--mf-detail-muted)}
.mf-detail-accordion__icon{display:grid;place-items:center;flex-shrink:0;width:32px;height:32px;background:#f5f5f5;border:1px solid #e5e5e5;border-radius:9px;color:#525252}
.mf-detail-accordion__icon svg{width:17px;height:17px}
.mf-detail-accordion__chevron{width:18px;height:18px;flex-shrink:0;color:#737373;transition:transform 350ms cubic-bezier(.215,.61,.355,1)}
.mf-detail-accordion__item[data-open="true"] .mf-detail-accordion__chevron{transform:rotate(180deg)}
.mf-detail-accordion__reveal{mask-image:linear-gradient(#000 max(calc(100% - 16px),calc(200% - var(--mf-auto-height-content,0px))),transparent)}
.mf-detail-accordion__panel{padding:2px 16px 18px;opacity:0;filter:blur(2px);transition:opacity 350ms cubic-bezier(.215,.61,.355,1),filter 350ms cubic-bezier(.215,.61,.355,1);min-width:0;font-size:13px;line-height:1.55}
.mf-detail-accordion__item[data-open="true"] .mf-detail-accordion__panel{opacity:1;filter:blur(0)}
.mf-detail-accordion__notice{margin:0 16px 14px;padding:10px 12px;border:1px solid #e5e5e5;border-radius:8px;background:#f5f5f5;color:#525252;font-size:12px;line-height:1.5;overflow-wrap:anywhere}
@media(max-width:480px){.mf-detail-accordion__trigger{padding:14px 12px;gap:9px}.mf-detail-accordion__panel{padding:2px 12px 16px}.mf-detail-accordion__notice{margin:0 12px 12px}}
@media(prefers-reduced-motion:reduce){.mf-detail-accordion__chevron,.mf-detail-accordion__panel,.mf-detail-accordion__trigger{transition:none}.mf-detail-accordion__panel{filter:none}.mf-detail-accordion__reveal{mask-image:none}}

.mf-detail-accordion__notice [role="alert"]{color:#b91c1c}
.mf-detail-accordion .mf-detail-accordion__panel :is(input,select,textarea)[aria-invalid="true"]{border-color:#b91c1c;color:#b91c1c;outline-color:#b91c1c}

'use client';

import { useLayoutEffect, useRef, type HTMLAttributes, type ReactNode } from 'react';
import { animate, useReducedMotion, type AnimationPlaybackControls } from 'motion/react';
import './auto-height.css';

export interface AutoHeightProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  /** Optional disclosure mode. Children stay mounted; the caller owns aria-hidden/inert. */
  collapsed?: boolean;
  contentClassName?: string;
}

/** Observes natural content size, including font, image and width changes.
 * Height and overflow on the outer element are owned by this component.
 * Idle expanded content is unclipped; initial content does not animate from zero.
 */
export function AutoHeight({ children, collapsed = false, className = '', contentClassName = '', ...props }: AutoHeightProps) {
  const outer = useRef<HTMLDivElement>(null);
  const inner = useRef<HTMLDivElement>(null);
  const animation = useRef<AnimationPlaybackControls | null>(null);
  const previous = useRef<number | null>(null);
  const measure = useRef<() => void>(() => {});
  const reduced = useReducedMotion();
  const latest = useRef({ collapsed, reduced });
  latest.current = { collapsed, reduced };

  useLayoutEffect(() => {
    const element = outer.current!;
    const content = inner.current!;
    let generation = 0;
    const settle = (isCollapsed: boolean) => {
      element.style.height = isCollapsed ? '0px' : 'auto';
      element.style.overflow = isCollapsed ? 'hidden' : 'visible';
      element.dataset.animating = 'false';
      animation.current = null;
    };
    measure.current = () => {
      const { collapsed: isCollapsed, reduced: reduce } = latest.current;
      const style = getComputedStyle(element);
      const chrome = ['paddingTop', 'paddingBottom', 'borderTopWidth', 'borderBottomWidth']
        .reduce((sum, key) => sum + (parseFloat(style[key as keyof CSSStyleDeclaration] as string) || 0), 0);
      const contentHeight = content.getBoundingClientRect().height;
      const target = isCollapsed ? 0 : contentHeight + chrome;
      // The disclosure's mask follows natural content height, not its animated
      // clipping box. At full height its fade reaches beyond the last pixel.
      element.style.setProperty('--mf-auto-height-content', `${contentHeight}px`);
      if (previous.current === target && !reduce) return;
      const from = animation.current ? element.getBoundingClientRect().height : previous.current;
      const token = ++generation;
      animation.current?.stop();
      previous.current = target;
      if (from === null || reduce || Math.abs(from - target) < 0.1) {
        settle(isCollapsed);
        return;
      }
      element.style.height = `${from}px`;
      element.style.overflow = 'hidden';
      element.dataset.animating = 'true';
      animation.current = animate(element, { height: target }, {
        type: 'spring', stiffness: 300, damping: 30, restDelta: 0.1,
        onComplete: () => { if (token === generation) settle(isCollapsed); },
      });
    };
    measure.current();
    const observer = new ResizeObserver(() => measure.current());
    observer.observe(content);
    return () => {
      generation++;
      observer.disconnect();
      animation.current?.stop();
      animation.current = null;
      previous.current = null;
      measure.current = () => {};
    };
  }, []);

  // React-driven updates are measured before paint; ResizeObserver covers all others.
  useLayoutEffect(() => { measure.current(); });

  return <div {...props} ref={outer} className={`mf-auto-height ${className}`} data-collapsed={collapsed || undefined}>
    <div ref={inner} className={`mf-auto-height__content ${contentClassName}`}>{children}</div>
  </div>;
}
